  "For example: prepare inputs, melt, refine, cast, roll. Confirm the actual monitoring boundary.":
    "Ví dụ: chuẩn bị đầu vào, nấu chảy, tinh luyện, đúc, cán. Xác nhận ranh giới giám sát thực tế.",
