  "Until all {total} are answered, every product report of this site stays Blocked and the report package stays locked — the reports open with these facts. Monthly data and precursors can still be entered meanwhile.":
    "Cho đến khi trả lời đủ {total} mục, mọi báo cáo sản phẩm của địa điểm này vẫn ở trạng thái Bị chặn và gói báo cáo bị khóa — các báo cáo sẽ mở khi có các thông tin này. Trong thời gian đó vẫn có thể nhập dữ liệu hằng tháng và tiền chất.",
  "Not asked here — read from your product reports":
    "Không hỏi ở đây — lấy từ báo cáo sản phẩm của bạn",
