  "What's left": "Còn lại",
  "Until all {total} are answered the product reports of this site read Blocked. You can still enter months and precursors.":
    "Cho đến khi trả lời đủ {total} mục, các báo cáo sản phẩm của địa điểm này hiển thị Bị chặn. Bạn vẫn có thể nhập tháng và tiền chất.",
