  "After that, changing an input creates a new version with a reason rather than silently moving a signed number.":
    "Sau đó, thay đổi dữ liệu đầu vào sẽ tạo phiên bản mới kèm lý do, thay vì âm thầm thay đổi một số đã ký.",
  "Calculation not frozen": "Tính toán chưa được đóng băng",
