  "No file to hand? Try an example": "Chưa có tệp? Thử một ví dụ",
  "Download one, then drop it above. Each holds only a few readings — enough to see how it works.":
    "Tải một tệp, rồi thả vào phía trên. Mỗi tệp chỉ có vài số đọc — đủ để thấy cách hoạt động.",
  "Choose one": "Chọn một",
