  "From the file": "Từ tệp",
  "This is what I found. Check each figure against your file and change anything that is not right — nothing goes into the form until you confirm.":
    "Đây là những gì tôi tìm thấy. Kiểm tra từng số liệu với tệp của bạn và sửa bất kỳ chỗ nào chưa đúng — không có gì được đưa vào biểu mẫu cho đến khi bạn xác nhận.",
  Include: "Bao gồm",
