  "Tonnes used": "Số tấn đã dùng",
  "Embedded emissions it carries": "Phát thải nhúng mang theo",
  "Adds {n} tCO₂e per tonne to this good.":
    "Cộng thêm {n} tCO₂e trên mỗi tấn cho hàng hóa này.",
  "The product report it came from no longer exists.":
    "Báo cáo sản phẩm mà nó xuất phát không còn tồn tại.",
  "Enter how many tonnes of it this good used.":
    "Nhập số tấn hàng hóa này đã dùng.",
  "This good has no production counted yet, so the quantity cannot be put per tonne.":
    "Hàng hóa này chưa có sản lượng được tính, nên không thể quy đổi số lượng theo tấn.",
  "Filled by Cera from {file}. Cera can make mistakes — check it against the document and edit it if it is wrong.":
    "Được Cera điền từ {file}. Cera có thể mắc lỗi — hãy đối chiếu với tài liệu và sửa nếu sai.",
  "Cera filled": "Cera đã điền",
  "Cera filled {n} values from your documents — they are in green.":
    "Cera đã điền {n} giá trị từ tài liệu của bạn — chúng có màu xanh lá.",
  "Cera can make mistakes — check each value against its document. Typing over a value makes it yours.":
    "Cera có thể mắc lỗi — hãy đối chiếu từng giá trị với tài liệu. Khi bạn gõ đè lên một giá trị, nó sẽ thành của bạn.",
  "Worked out from the stock change below.":
    "Tính từ biến động tồn kho bên dưới.",
