  "Process gases such as blast-furnace or coke-oven gas, by their energy content — or by volume and composition, gas by gas.":
    "Khí quy trình như khí lò cao hoặc khí lò luyện cốc, theo hàm lượng năng lượng — hoặc theo thể tích và thành phần, từng loại khí.",
