  "Average minutes per cell-day:": "Số phút trung bình trên mỗi ngày-bình:",
  "My cells are not all one type, or the lines run differently":
    "Các bình của tôi không cùng một loại, hoặc các dây chuyền vận hành khác nhau",
  "What the steel is made of": "Thép được làm từ gì",
  "Product composition": "Thành phần sản phẩm",
  "The alloying elements of what was made this month, from the mill test certificates, weighted by the heats cast.":
    "Các nguyên tố hợp kim của sản phẩm làm ra trong tháng này, theo chứng chỉ thử nghiệm nhà máy, có trọng số theo số mẻ đúc.",
  "The report states Mn, Cr, Ni and the other alloying elements for the year: the months' figures, weighted by what was made in each. Leave a month empty if it was ordinary carbon steel with only trace elements.":
    "Báo cáo ghi Mn, Cr, Ni và các nguyên tố hợp kim khác cho cả năm: số liệu của từng tháng, có trọng số theo sản lượng làm ra trong mỗi tháng. Để trống một tháng nếu đó là thép carbon thông thường chỉ có nguyên tố vết.",
  "Optional. Weighted by tonnes made across the year in the report.":
    "Tùy chọn. Có trọng số theo số tấn sản xuất trong cả năm của báo cáo.",
