  "What goes to the verifier": "Những gì gửi cho thẩm định viên",
  "Everything this installation hands over for {year}, in one package: the reports you write, and the papers that travel with them.":
    "Mọi thứ cơ sở này bàn giao cho {year}, trong một gói: các báo cáo bạn lập và các giấy tờ đi kèm.",
  Attachments: "Tệp đính kèm",
  "Not reports you write. Each is an index of papers that travel in the package, beside the reports — and neither holds the package back.":
    "Không phải báo cáo bạn tự lập. Mỗi mục là danh mục các giấy tờ đi kèm trong gói, bên cạnh các báo cáo — và không mục nào làm chậm gói.",
  "Monitoring plan, operator's emissions report, summary report":
    "Kế hoạch giám sát, báo cáo phát thải của người vận hành, báo cáo tóm tắt",
  Addendum: "Phụ lục bổ sung",
  "Electricity goes to the EU — one per declarant":
    "Điện được gửi vào EU — một cho mỗi người khai báo",
  "Not needed — no electricity goes to the EU":
    "Không cần — không có điện nào được gửi vào EU",
  "Precursor verification reports, supporting evidence":
    "Báo cáo thẩm định của tiền chất, bằng chứng hỗ trợ",
  Contains: "Bao gồm",
  "to get": "cần lấy",
  "Still to get": "Còn cần lấy",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.":
    "Mỗi cơ sở bạn báo cáo bàn giao một gói mỗi năm: kế hoạch giám sát, báo cáo phát thải của người vận hành và báo cáo tóm tắt — kèm phụ lục của người khai báo khi điện được gửi vào EU — và bên cạnh đó là báo cáo thẩm định của các cơ sở sản xuất tiền chất và các bằng chứng hỗ trợ. Gói bao gồm mọi sản phẩm cơ sở sản xuất và chỉ tải xuống khi đã hoàn tất đầy đủ.",
  documents: "tài liệu",
  "The product report is not complete": "Báo cáo sản phẩm chưa hoàn tất",
  "{n} of {total} product reports are not complete":
    "{n} trên {total} báo cáo sản phẩm chưa hoàn tất",
  "{n} item(s) of the installation's information are still missing":
    "Còn thiếu {n} mục thông tin của cơ sở",
  "{n} item(s) to do": "{n} mục cần làm",
  "Monitoring plan": "Kế hoạch giám sát",
  "Operator's emissions report": "Báo cáo phát thải của người vận hành",
  "Operator's summary emissions report":
    "Báo cáo tóm tắt phát thải của người vận hành",
  "Declarant-specific addendum": "Phụ lục riêng cho người khai báo",
  "Verification reports of precursor installations":
    "Báo cáo thẩm định của các cơ sở tiền chất",
  "Supporting evidence and records": "Bằng chứng và hồ sơ hỗ trợ",
  "What the installation monitors and how, element by element as the template lists them. The verifier reads it before the year is verified.":
    "Cơ sở giám sát những gì và bằng cách nào, từng yếu tố theo mẫu liệt kê. Thẩm định viên đọc trước khi năm được thẩm định.",
  "The full report the verifier verifies. It is in English (Article 10(4)).":
    "Báo cáo đầy đủ mà thẩm định viên thẩm định. Được lập bằng tiếng Anh (Điều 10(4)).",
  "The shortened report passed on to authorised CBAM declarants (Article 8).":
    "Báo cáo rút gọn chuyển cho người khai báo CBAM được ủy quyền (Điều 8).",
  "One per authorised declarant, only for electricity imported into the EU.":
    "Một cho mỗi người khai báo được ủy quyền, chỉ dành cho điện nhập khẩu vào EU.",
  "This installation does not export electricity to the EU, so no addendum is needed.":
    "Cơ sở này không xuất điện sang EU, nên không cần phụ lục.",
  "The verification reports of the installations that made your precursors on actual values. The reports themselves are in the package, beside this index.":
    "Báo cáo thẩm định của các cơ sở đã sản xuất tiền chất của bạn theo giá trị thực tế. Chính các báo cáo nằm trong gói, bên cạnh danh mục này.",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper. The documents themselves are in the package, beside this index.":
    "Mọi tài liệu đứng sau một con số và con số mà nó hỗ trợ, để thẩm định viên có thể lấy mẫu một tháng và tìm được giấy tờ của tháng đó. Chính các tài liệu nằm trong gói, bên cạnh danh mục này.",
  "Operator and installation": "Người vận hành và cơ sở",
  "1 · Operator and installation": "1 · Người vận hành và cơ sở",
