  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.":
    "Kéo thả hóa đơn, hóa đơn nhiên liệu và xuất ERP của tháng này. AI đọc từng tệp, lưu lại và điền các số liệu tương ứng. Bạn kiểm tra mọi thứ trước khi lưu — AI có thể mắc lỗi.",
  "Add documents & auto-fill": "Thêm tài liệu và tự động điền",
  "AI reads your bills and invoices and fills the form. You check before saving — AI can make mistakes.":
    "AI đọc hóa đơn và phiếu xuất của bạn rồi điền biểu mẫu. Bạn kiểm tra trước khi lưu — AI có thể mắc lỗi.",
  "Why this is asked": "Vì sao được hỏi",
