  "{name} — {suppliers} suppliers · {products} products · {lots} lots queued.":
    "{name} — {suppliers} nhà cung cấp · {products} sản phẩm · {lots} lô đang chờ.",
  "Compliance regulation": "Quy định tuân thủ",
  "Which regime are you reporting for? Certrace launched on CBAM — the obligation that bites first for exporters into the EU. The rest run on the same engine and switch on as their data models are verified.":
    "Bạn đang khai báo theo chế độ nào? Certrace ra mắt với CBAM — nghĩa vụ có hiệu lực sớm nhất đối với nhà xuất khẩu vào EU. Các chế độ còn lại chạy trên cùng một động cơ và sẽ được bật khi mô hình dữ liệu của chúng đã được thẩm định.",
  "Export route": "Tuyến xuất khẩu",
  "Where do you export from, and into which market? {reg} applies to goods entering the EU — your origin sets the emission-factor library Certrace calculates with.":
    "Bạn xuất khẩu từ đâu, và vào thị trường nào? {reg} áp dụng cho hàng hóa nhập vào EU — xuất xứ của bạn quyết định thư viện hệ số phát thải mà Certrace dùng để tính toán.",
  "From — country of origin": "Từ — nước xuất xứ",
