    "Sổ đăng ký CBAM của EU · qua người nhập khẩu / người khai báo",
  "What is this declaration for?": "Tờ khai này dùng để làm gì?",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.":
    "Chọn một — hoặc khai báo CBAM chính thức, hoặc yêu cầu dữ liệu cụ thể của một người mua. Mỗi loại có danh mục kiểm tra điều kiện riêng, nên hãy tách biệt hai loại này.",
  "CBAM Compliance": "Tuân thủ CBAM",
  "Automatically prepares supplier data collection based on CBAM requirements. Fields, CN codes and templates are generated for you.":
    "Tự động chuẩn bị thu thập dữ liệu nhà cung cấp theo yêu cầu CBAM. Các trường, mã CN và mẫu được tạo sẵn cho bạn.",
  "Buyer Request": "Yêu cầu của người mua",
  "Create a custom supplier request for buyer-specific information — documents, certificates and questionnaires on top of the carbon data.":
    "Tạo yêu cầu nhà cung cấp tùy chỉnh để lấy thông tin riêng của người mua — tài liệu, chứng chỉ và bảng câu hỏi bổ sung cho dữ liệu carbon.",
  "e.g. CBAM 2026 Annual": "ví dụ: CBAM 2026 Hằng năm",
  "e.g. ABC Buyer Carbon Data Request":
    "ví dụ: Yêu cầu dữ liệu carbon của người mua ABC",
  "Request name": "Tên yêu cầu",
  "Shown to suppliers and on every reminder. Make it recognisable.":
    "Hiển thị cho nhà cung cấp và trong mọi lời nhắc. Hãy đặt tên dễ nhận biết.",
  "Request description (optional)": "Mô tả yêu cầu (tùy chọn)",
  "Context for your suppliers — what this is for.":
    "Bối cảnh cho nhà cung cấp — yêu cầu này dùng để làm gì.",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.":
    "ví dụ: Dữ liệu carbon CBAM hằng năm cho xuất khẩu thép sang EU của chúng tôi. Vui lòng báo cáo ở cấp cơ sở.",
  "EU buyer / importer (required)": "Người mua / nhập khẩu tại EU (bắt buộc)",
  "EU buyer / importer": "Người mua / nhập khẩu tại EU",
  "Who imports these goods into the EU? Their Authorised CBAM Declarant files the declaration — Certrace addresses the Communication Template and the O3CI share to them.":
    "Ai nhập khẩu các hàng hóa này vào EU? Người khai báo CBAM được ủy quyền của họ sẽ nộp tờ khai — Certrace gửi Mẫu thông báo và phần O3CI cho họ.",
  "The buyer this data request is for.":
    "Người mua mà yêu cầu dữ liệu này dành cho.",
  "Buyer legal name": "Tên pháp lý của người mua",
  "EORI number": "Số EORI",
  "Format: 2-letter country + 6–15 characters, e.g. DE551234567890":
    "Định dạng: mã quốc gia 2 chữ + 6–15 ký tự, ví dụ DE551234567890",
  "The declarant's Registry identifier.":
    "Mã định danh trong Sổ đăng ký của người khai báo.",
