  "Where the Communication Template is sent.": "Nơi gửi Mẫu thông báo.",
  "Buyer requests can run on any cadence. Pick the rhythm that matches how this buyer wants the data.":
    "Yêu cầu của người mua có thể chạy theo bất kỳ tần suất nào. Chọn nhịp phù hợp với cách người mua này muốn nhận dữ liệu.",
  "Official CBAM declarations are annual — but you can collect supplier data quarterly if that fits your cycle.":
    "Tờ khai CBAM chính thức là hằng năm — nhưng bạn có thể thu thập dữ liệu nhà cung cấp theo quý nếu phù hợp với chu kỳ của bạn.",
