  "These are the data points CBAM requires for the goods you selected. Required fields are locked on; the rest are recommended and on by default — keep or drop them to match how you collect data.":
    "Đây là các điểm dữ liệu CBAM yêu cầu cho hàng hóa bạn đã chọn. Các trường bắt buộc được bật cố định; các trường còn lại được khuyến nghị và bật mặc định — giữ hoặc bỏ để phù hợp với cách bạn thu thập dữ liệu.",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.":
    "Chọn các trường dữ liệu carbon mà người mua này cần. Các trường được khuyến nghị đã được chọn sẵn vì người mua thường yêu cầu — có thể điều chỉnh tự do, nhưng giữ lại ít nhất một trường.",
