  "Map suppliers to each product, then add the production lots you bought in this period. Each lot keeps its own quantity and optional production period, so the embedded-emissions calculation stays fully traceable.":
    "Gán nhà cung cấp cho từng sản phẩm, rồi thêm các lô sản xuất bạn đã mua trong kỳ này. Mỗi lô giữ số lượng riêng và kỳ sản xuất tùy chọn, nhờ đó phép tính phát thải nhúng luôn truy vết được đầy đủ.",
  "We produce this ourselves": "Chúng tôi tự sản xuất",
