    "Gói {plan} của bạn chỉ có một chỗ trong nhóm, và đã có người.",
  "Talk to sales to raise it — suppliers stay free and unlimited either way.":
    "Liên hệ bộ phận bán hàng để nâng cấp — nhà cung cấp vẫn miễn phí và không giới hạn trong mọi trường hợp.",
