  "see what each tier includes →": "xem mỗi gói bao gồm gì →",
  "Every seat on your plan is taken. Remove someone to free one, or talk to sales — suppliers still cost nothing and never take a seat.":
    "Mọi chỗ trong gói của bạn đã có người. Xóa một người để giải phóng chỗ, hoặc liên hệ bộ phận bán hàng — nhà cung cấp vẫn miễn phí và không chiếm chỗ.",
  "free and unlimited on every plan": "miễn phí và không giới hạn trên mọi gói",
  "Suppliers are free and unlimited on every tier, at any chain depth, and never take a seat.":
    "Nhà cung cấp miễn phí và không giới hạn trên mọi cấp, ở bất kỳ độ sâu chuỗi nào, và không chiếm chỗ.",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers one site.":
    "Mọi cơ sở do bạn tự vận hành. Đăng ký một lần tại đây và dữ liệu hằng tháng của chúng sẽ về hộp thư đến của bạn thay vì gửi cho nhà cung cấp. Gói của bạn bao phủ một cơ sở.",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers {cap} sites.":
    "Mọi cơ sở do bạn tự vận hành. Đăng ký một lần tại đây và dữ liệu hằng tháng của chúng sẽ về hộp thư đến của bạn thay vì gửi cho nhà cung cấp. Gói của bạn bao phủ {cap} cơ sở.",
  "CN {code} would be a new code on your plan.":
    "Mã CN {code} sẽ là một mã mới trên gói của bạn.",
  "Codes you already report — and any number of sites or years reporting them — cost nothing more.":
    "Các mã bạn đã báo cáo — và bất kỳ số cơ sở hay năm nào báo cáo chúng — không tốn thêm chi phí.",
