    "Mã này là cố định và không bao giờ thay đổi — tờ khai, nhà cung cấp và chỗ của bạn vẫn gắn với mã này ngay cả khi email bên dưới thay đổi. Nếu người thiết lập tài khoản này rời công ty, quyền sở hữu có thể chuyển sang email mới mà không mất lịch sử nào.",
