  "Where the carbon is.": "Carbon nằm ở đâu.",
  "Every declaration in one place: what the certificates cost, which suppliers and goods carry the emissions, and whose data has aged past the point you should still be filing it.":
    "Mọi tờ khai ở một nơi: chứng chỉ có chi phí bao nhiêu, nhà cung cấp và hàng hóa nào mang phát thải, và dữ liệu của ai đã cũ đến mức không còn nên dùng để nộp nữa.",
  "Open cycles": "Chu kỳ đang mở",
  "All time": "Toàn bộ thời gian",
  "Reading supplier records…": "Đang đọc hồ sơ nhà cung cấp…",
  "No approved emissions data yet.":
    "Chưa có dữ liệu phát thải nào được duyệt.",
  "Once suppliers submit and you approve their figures, the cost, the hotspots and the benchmark all appear here — across every declaration at once.":
    "Khi nhà cung cấp gửi và bạn duyệt số liệu của họ, chi phí, điểm nóng và chuẩn so sánh sẽ hiện ở đây — trên mọi tờ khai cùng lúc.",
  "Go to declarations": "Đến tờ khai",
  "Certificate cost": "Chi phí chứng chỉ",
  "Chargeable tCO₂e": "tCO₂e phải nộp",
  "{tonnes} t reported": "{tonnes} t đã báo cáo",
  "Suppliers costed": "Nhà cung cấp đã tính chi phí",
  "Saved vs defaults": "Tiết kiệm so với mặc định",
  "Above defaults": "Cao hơn mặc định",
  "real data vs fallback": "dữ liệu thực tế so với dự phòng",
  "Priced at": "Giá tính theo",
  "{amount} on every tonne you ship. An estimate for planning: the declarant buys at the published auction average for the week of import.":
    "{amount} trên mỗi tấn bạn giao. Ước tính để lập kế hoạch: người khai báo mua theo mức trung bình đấu giá đã công bố trong tuần nhập khẩu.",
  "Certificate price in EUR per tonne CO2e":
    "Giá chứng chỉ tính bằng EUR trên mỗi tấn CO2e",
  "Carbon hotspots": "Điểm nóng carbon",
  "Ranked by absolute chargeable emissions across every declaration in scope — the same mill appearing on four filings counts once, as one relationship.":
    "Xếp hạng theo phát thải phải nộp tuyệt đối trên mọi tờ khai trong phạm vi — cùng một nhà máy xuất hiện trong bốn hồ sơ chỉ được tính một lần, như một mối quan hệ.",
  "by supplier": "theo nhà cung cấp",
  "by product": "theo sản phẩm",
  "{count} of {total} suppliers": "{count} trên {total} nhà cung cấp",
  "carry {pct}% of your chargeable emissions — about {amount} in certificates. That's the shortlist for a conversation about actual data, a cleaner route, or a different supplier.":
    "chiếm {pct}% phát thải phải nộp của bạn — khoảng {amount} tiền chứng chỉ. Đây là danh sách rút gọn để trao đổi về dữ liệu thực tế, tuyến sạch hơn, hoặc một nhà cung cấp khác.",
  "Data that needs refreshing": "Dữ liệu cần cập nhật",
  "Supplier records age. A figure past a year, or one reported for a period you're no longer filing, has to be re-confirmed before it goes into another declaration.":
    "Hồ sơ nhà cung cấp sẽ cũ đi. Số liệu quá một năm, hoặc số liệu báo cáo cho kỳ bạn không còn nộp nữa, phải được xác nhận lại trước khi đưa vào tờ khai khác.",
  "No supplier records yet — they build up as suppliers submit, and each one makes the next request shorter.":
    "Chưa có hồ sơ nhà cung cấp — hồ sơ sẽ tích lũy khi nhà cung cấp gửi, và mỗi hồ sơ làm yêu cầu tiếp theo ngắn hơn.",
  "Your one supplier record is current.":
    "Hồ sơ nhà cung cấp duy nhất của bạn còn hiệu lực.",
  "All {count} supplier records are current.":
    "Cả {count} hồ sơ nhà cung cấp đều còn hiệu lực.",
  "{count} goods on file": "{count} hàng hóa trong hồ sơ",
  "fed {count} declarations": "đưa vào {count} tờ khai",
  "last updated {days}d ago": "cập nhật lần cuối {days} ngày trước",
  "What this is built from": "Dữ liệu được xây dựng từ đâu",
  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.":
    "{datasets} bộ dữ liệu nhà cung cấp đã gửi trên {declarations} tờ khai, được tính chi phí bằng cùng động cơ mà không gian làm việc tờ khai sử dụng — quy tắc chỉ trực tiếp theo Phụ lục II cho thép và nhôm, hệ số tăng thêm giá trị mặc định khi nhà cung cấp báo cáo theo mặc định, và trừ mọi giá carbon đã nộp. Không có số liệu nào ở đây là số liệu đã nộp.",
