  "All groups": "Tất cả nhóm",
  Restore: "Khôi phục",
  "Restore workspace": "Khôi phục không gian làm việc",
  "Continue where you left off": "Tiếp tục từ chỗ bạn đã dừng",
  "Nothing here is transmitted automatically — this browser only, until you submit.":
    "Không có gì ở đây được truyền tự động — chỉ lưu trên trình duyệt này, cho đến khi bạn gửi.",
  "Saved as you go — you can close this page and come back to it from any device.":
    "Tự động lưu khi bạn nhập — bạn có thể đóng trang và quay lại từ bất kỳ thiết bị nào.",
  "Back to declarations": "Quay lại khai báo",
  "Submitting…": "Đang gửi…",
  "Edit requested": "Đã yêu cầu chỉnh sửa",
  Frozen: "Đã khóa",
  Assumption: "Giả định",
  "Accept with a reason": "Chấp nhận kèm lý do",
  "Verification report": "Báo cáo thẩm định",
  "Generate buyer summary package": "Tạo gói tóm tắt cho người mua",
  "avoided this year, so far": "đã tránh được trong năm nay, cho đến nay",
  "Suppliers and Reports stay in the left nav — they are quick, frequent jobs, and burying them under a declaration would guarantee they never get done.":
    "Nhà cung cấp và Báo cáo nằm ở thanh điều hướng bên trái — đây là các việc nhanh, thường xuyên, và nếu chôn chúng dưới một khai báo thì chắc chắn sẽ không bao giờ được làm.",
  "No anomalies or gaps — figures are complete, in range and standardised.":
    "Không có bất thường hay khoảng thiếu — số liệu đầy đủ, nằm trong phạm vi và đã chuẩn hóa.",
  "Send revision request": "Gửi yêu cầu chỉnh sửa",
  "sha-256 sealed · verification trail + version history embedded":
    "đã niêm phong sha-256 · kèm theo dấu vết thẩm định + lịch sử phiên bản",
  "Generate package": "Tạo gói",
  "Schema valid for definitive period":
    "Lược đồ hợp lệ cho giai đoạn chính thức",
  "strict schema validation": "kiểm tra lược đồ nghiêm ngặt",
  "Download XML": "Tải XML",
  "Send for confirmation": "Gửi để xác nhận",
  "Their copy": "Bản của họ",
  "Send template": "Gửi mẫu",
  "Add buyer": "Thêm người mua",
  "Add another buyer for this dataset":
    "Thêm người mua khác cho bộ dữ liệu này",
  "Add an upstream precursor of theirs": "Thêm tiền chất thượng nguồn của họ",
  "Enter it by hand instead": "Nhập thủ công thay thế",
  "carried over": "đã chuyển sang",
  "Scrap / waste": "Phế liệu / chất thải",
  "Why you are being asked to check this":
    "Vì sao bạn được yêu cầu kiểm tra mục này",
  "What a boundary is": "Ranh giới là gì",
  "Add the first process…": "Thêm quy trình đầu tiên…",
