  "submitted earlier": "đã gửi trước đó",
  "not started (critical)": "chưa bắt đầu (quan trọng)",
  "No Smart Link goes out for these — {supplier} is you. Report the embedded emissions of your own installation the same way an external supplier would, and the declaration treats it identically: same {regulation} checklist, same AI check, same verification trail.":
    "Không gửi Smart Link cho các mục này — {supplier} chính là bạn. Hãy báo cáo phát thải nhúng của cơ sở của bạn giống như một nhà cung cấp bên ngoài, và khai báo sẽ xử lý giống hệt: cùng danh mục kiểm tra {regulation}, cùng kiểm tra AI, cùng dấu vết thẩm định.",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.":
    "Bạn là {supplier}. Để tiếp tục xuất {origin} {sector} sang {destination}, {exporter} phải báo cáo phát thải nhúng của hàng hóa họ mua từ bạn — theo {regulation}. Việc này mất khoảng 10 phút, miễn phí, và bạn không cần tài khoản.",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.":
    "Số liệu của bạn được kiểm tra tự động trước khi gửi và được lưu vào hồ sơ nhà cung cấp của chính bạn, nên khai báo tiếp theo sẽ bắt đầu với dữ liệu đã điền sẵn thay vì trống. Có thể giao các mục thuộc bộ phận của đồng nghiệp cho họ.",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.":
    "Số liệu của bạn được kiểm tra tự động trước khi gửi, được mã hóa, và chỉ chia sẻ với {exporter} cho khai báo này. Bạn có thể mời đồng nghiệp điền các phần thuộc bộ phận của họ.",
  "Reporting as": "Báo cáo với vai trò",
