    "Mục này sẽ được điền khi báo cáo sản phẩm có ít nhất một tháng đã gửi.",
  "Carry the submitted months across the year at the same rate. An assumption, not a forecast.":
    "Áp dụng tỷ lệ tương tự cho các tháng đã gửi trong cả năm. Đây là giả định, không phải dự báo.",
