  "Used to show every euro figure in baht, yuan and rupees.":
    "Dùng để hiển thị mọi số liệu euro bằng baht, nhân dân tệ và rupee.",
  "The cross-sectoral correction factor is taken as 1: the Commission has not published it in the rules this was built from.":
    "Hệ số hiệu chỉnh liên ngành được lấy bằng 1: Ủy ban chưa công bố hệ số này trong các quy tắc làm cơ sở cho công cụ này.",
  "A bought-in precursor's own free allocation is not netted off, so a complex good's cost is never shown lower than it is.":
    "Hạn mức phân bổ miễn phí của tiền chất mua vào không được trừ đi, nên chi phí của hàng hóa phức hợp không bao giờ được hiển thị thấp hơn thực tế.",
