  "When the trial ends the account becomes read-only: you can still open everything, but nothing can be changed, sent or downloaded.":
    "Khi thời gian dùng thử kết thúc, tài khoản chuyển sang chỉ đọc: bạn vẫn có thể mở mọi thứ, nhưng không thể thay đổi, gửi hoặc tải xuống.",
  "Choose a plan before then to keep working without a break.":
    "Hãy chọn gói trước thời điểm đó để tiếp tục làm việc không gián đoạn.",
