  "Supply Chain scores every supplier and precursor on how reliably the data arrives, and says where it worries us.":
    "Chuỗi cung ứng chấm điểm mọi nhà cung cấp và tiền chất theo mức độ dữ liệu đến đúng hạn và đáng tin cậy, và cho biết những điểm đáng lo.",
  "Notifications — {n} unread": "Thông báo — {n} chưa đọc",
  "Sample notifications — your own data is not touched.":
    "Thông báo mẫu — dữ liệu của bạn không bị thay đổi.",
  "Nothing to tell you right now.": "Hiện chưa có gì cần thông báo.",
  "See all {n}": "Xem tất cả {n}",
  "See all notifications": "Xem tất cả thông báo",
  "System message": "Thông báo hệ thống",
  "Message from Certrace": "Thông báo từ Certrace",
  "From Certrace": "Từ Certrace",
  "This is the rules as Certrace has them, not a live feed. Check the official text before you rely on it.":
    "Đây là các quy tắc như Certrace đang có, không phải nguồn cập nhật trực tiếp. Hãy kiểm tra văn bản chính thức trước khi dựa vào.",
  "Open Coverage": "Mở Phạm vi",
  Unread: "Chưa đọc",
  Account: "Tài khoản",
  "What needs you, what has just happened, and what Certrace has to tell you — drawn from the same figures as the dashboard.":
    "Những việc cần bạn, những gì vừa xảy ra, và những gì Certrace cần thông báo — lấy từ cùng số liệu với bảng điều khiển.",
  "Sample notifications.": "Thông báo mẫu.",
  "These come from the made-up estate on the dashboard. Your own data is not touched.":
    "Các thông báo này đến từ danh mục mô phỏng trên bảng điều khiển. Dữ liệu của bạn không bị thay đổi.",
  "Needs action": "Cần xử lý",
  Happened: "Đã xảy ra",
  Messages: "Tin nhắn",
  "A notice appears when a month runs late, a supplier answers, a package is ready, or Certrace has something to say.":
    "Thông báo xuất hiện khi một tháng bị trễ, nhà cung cấp trả lời, gói đã sẵn sàng, hoặc Certrace có điều cần nói.",
  "CBAM news": "Tin tức CBAM",
  "Rule changes, new certificate prices and the dates that matter — as Certrace has them.":
    "Thay đổi quy tắc, giá chứng chỉ mới và các mốc thời gian quan trọng — theo cách Certrace đang có.",
  "Your trial, the limits of your plan and anything that needs your attention on it.":
    "Thời gian dùng thử, giới hạn của gói và mọi việc cần bạn chú ý.",
  "Thailand's excise on oil products, which carries a carbon component of THB 200/tCO₂e — Excise Department notice in the Government Gazette of 22 April 2025, unchanged at 26 October 2026":
    "Thuế tiêu thụ đặc biệt của Thái Lan đối với sản phẩm dầu, có thành phần carbon 200 THB/tCO₂e — thông báo của Cục Thuế tiêu thụ đặc biệt trên Công báo Chính phủ ngày 22 tháng 4 năm 2025, không thay đổi tính đến ngày 26 tháng 10 năm 2026",
  "Monthly schedule": "Lịch hàng tháng",
  "The day of the month each month's data is due.":
    "Ngày trong tháng mà dữ liệu của mỗi tháng đến hạn.",
  "The report": "Báo cáo",
  "Brought across as a draft you can edit. A finished version is never copied.":
    "Được chuyển sang dưới dạng bản nháp bạn có thể chỉnh sửa. Phiên bản đã hoàn tất không bao giờ được sao chép.",
  "Boundary and processes": "Ranh giới và quy trình",
  "The boundary description, the processes inside it and what is left out, with the ground for each.":
    "Mô tả ranh giới, các quy trình bên trong và những gì bị loại trừ, cùng cơ sở cho từng mục.",
  "Fuels and electricity": "Nhiên liệu và điện",
  "The fuels burned, the electricity supply and the meter it is read from.":
    "Các nhiên liệu đã đốt, nguồn cung điện và đồng hồ đo được đọc.",
  "Measuring instruments": "Thiết bị đo lường",
  "The instrument and the reading frequency for each fuel and for electricity.":
    "Thiết bị và tần suất đọc số cho từng nhiên liệu và cho điện.",
  "The estimates standing in for missing readings. They describe last year, so they start new unless you choose otherwise.":
    "Các ước tính thay thế cho số đọc bị thiếu. Chúng mô tả năm trước, nên sẽ bắt đầu lại từ đầu trừ khi bạn chọn khác.",
  "Who reviews the data, and how often.":
    "Ai rà soát dữ liệu, và bao lâu một lần.",
  "The drawing of the installation and what it shows.":
    "Bản vẽ của cơ sở và những gì nó thể hiện.",
  "Steel: the reducing agent and the mill. Aluminium: the way perfluorocarbons are counted.":
    "Thép: tác nhân khử và nhà máy cán. Nhôm: cách tính perfluorocarbon.",
  "Sampling plan": "Kế hoạch lấy mẫu",
  "How the calculation factors are determined.":
    "Cách xác định các hệ số tính toán.",
  "Control system": "Hệ thống kiểm soát",
  "The controls that keep the data right.":
    "Các biện pháp kiểm soát giữ cho dữ liệu chính xác.",
  "Who supplies what, in the same tree: names, countries, CN codes, routes and contacts. Not their figures, reports or links — those are asked again.":
    "Ai cung cấp gì, trong cùng một cây: tên, quốc gia, mã CN, tuyến và liên hệ. Không bao gồm số liệu, báo cáo hoặc liên kết của họ — những thứ này sẽ được yêu cầu lại.",
  "The instrument, the amount per tonne, the law it is charged under and who certifies it. The receipt and any rebate are left behind.":
    "Thiết bị, số tiền trên mỗi tấn, luật mà nó được tính theo và ai chứng nhận. Biên lai và mọi khoản hoàn trả sẽ không được chuyển.",
  "Who makes it": "Ai sản xuất",
  "The supplier, or your own site.": "Nhà cung cấp, hoặc cơ sở của chính bạn.",
  "Monthly figures": "Số liệu hàng tháng",
  "Production, fuels and electricity for each month.":
    "Sản lượng, nhiên liệu và điện của từng tháng.",
  "Documents and evidence": "Tài liệu và bằng chứng",
  "Receipts, invoices, calibration certificates.":
    "Biên lai, hóa đơn, chứng nhận hiệu chuẩn.",
  "Sign-offs and finished versions": "Phê duyệt và phiên bản đã hoàn tất",
  "The approvals and the stamped monitoring plans of the year behind it.":
    "Các phê duyệt và phương pháp giám sát đã đóng dấu của năm làm cơ sở.",
  "Worked out again from the new year's figures.":
    "Được tính lại từ số liệu của năm mới.",
