  "For each part, choose whether it comes across or starts new.":
    "Với mỗi phần, chọn chuyển sang hoặc bắt đầu mới.",
  "Bring everything across": "Chuyển tất cả",
  "Start everything new": "Bắt đầu mới tất cả",
  "Bring across": "Chuyển sang",
  "Start new": "Bắt đầu mới",
  "This is a different site, so the parts that describe the old plant start new. Switch any back on if they fit.":
    "Đây là một cơ sở khác, nên các phần mô tả nhà máy cũ sẽ bắt đầu mới. Bật lại bất kỳ phần nào nếu phù hợp.",
  "Always comes across": "Luôn được chuyển sang",
  "Always starts new": "Luôn bắt đầu mới",
  "They belong to the year they describe, so a copy never brings them.":
    "Chúng thuộc về năm mà chúng mô tả, nên bản sao không bao giờ mang theo chúng.",
  "{n} of {total} parts come across. The rest start new.":
    "{n} trên {total} phần được chuyển sang. Phần còn lại bắt đầu mới.",
  "Nothing comes across — everything starts new.":
    "Không có gì được chuyển sang — mọi thứ bắt đầu mới.",
  "All {n} parts come across.": "Cả {n} phần đều được chuyển sang.",
  "1 item is overdue.": "1 mục đã quá hạn.",
  "{n} items are overdue.": "{n} mục đã quá hạn.",
  "1 month past the deadline and still unanswered":
    "1 tháng đã quá hạn và vẫn chưa được trả lời",
  "{n} months past the deadline and still unanswered":
    "{n} tháng đã quá hạn và vẫn chưa được trả lời",
