  "{n} months ready to send: nobody has been asked yet":
    "{n} tháng sẵn sàng gửi: chưa ai được yêu cầu",
  "1 product has no EU volume entered, so all the tonnes made are assumed shipped to the EU.":
    "1 sản phẩm chưa nhập sản lượng xuất sang EU, nên mọi tấn đã sản xuất được giả định là đã xuất sang EU.",
  "{n} products have no EU volume entered, so all the tonnes made are assumed shipped to the EU.":
    "{n} sản phẩm chưa nhập sản lượng xuất sang EU, nên mọi tấn đã sản xuất được giả định là đã xuất sang EU.",
  "A carbon price paid at home is recorded for 1 product. It is shown as claimed and never subtracted.":
    "Giá carbon đã nộp trong nước được ghi nhận cho 1 sản phẩm. Khoản này được hiển thị như đã yêu cầu và không bao giờ bị trừ.",
  "A carbon price paid at home is recorded for {n} products. It is shown as claimed and never subtracted.":
    "Giá carbon đã nộp trong nước được ghi nhận cho {n} sản phẩm. Khoản này được hiển thị như đã yêu cầu và không bao giờ bị trừ.",
  "Add the price of 1 energy item to see this.":
    "Thêm giá của 1 mục năng lượng để xem.",
  "Add the price of {n} energy items to see this.":
    "Thêm giá của {n} mục năng lượng để xem.",
  "1 item of the installation's information is still missing":
    "Còn thiếu 1 mục thông tin của cơ sở",
  "{n} items of the installation's information are still missing":
    "Còn thiếu {n} mục thông tin của cơ sở",
  "1 item to do": "1 mục cần làm",
  "{n} items to do": "{n} mục cần làm",
  "1 month is not submitted, so the annual figure is **incomplete, not smaller**. Every per-tonne figure above divides by a denominator that is missing that month, which overstates them.":
    "1 tháng chưa được gửi, nên số liệu cả năm là **chưa đầy đủ, chứ không phải nhỏ hơn**. Mọi số liệu trên mỗi tấn ở trên đều chia cho mẫu số thiếu tháng đó, nên làm chúng bị đánh giá cao hơn.",
  "{n} months are not submitted, so the annual figure is **incomplete, not smaller**. Every per-tonne figure above divides by a denominator that is missing those months, which overstates them.":
    "{n} tháng chưa được gửi, nên số liệu cả năm là **chưa đầy đủ, chứ không phải nhỏ hơn**. Mọi số liệu trên mỗi tấn ở trên đều chia cho mẫu số thiếu những tháng đó, nên làm chúng bị đánh giá cao hơn.",
  "{fuel} fuel + {process} process": "Nhiên liệu {fuel} + quy trình {process}",
  "{n} months are overdue": "{n} tháng đã quá hạn",
  "{product} · the oldest is {month}, {days} days late":
    "{product} · cũ nhất là {month}, trễ {days} ngày",
  "Plans sized to your filing.": "Các gói được thiết kế theo hồ sơ của bạn.",
  "Annual term. A plan counts your own side — companies, installations, CN codes, precursors and seats. Suppliers and precursor suppliers enter and fill in through their smart link on every plan, without limit.":
    "Thời hạn hằng năm. Gói tính theo phía của bạn — công ty, cơ sở, mã CN, tiền chất và chỗ ngồi. Nhà cung cấp và nhà cung cấp tiền chất nhập và điền dữ liệu qua smart link của họ trong mọi gói, không giới hạn.",
  "smart links unlimited": "smart link không giới hạn",
  "{n} pages": "{n} trang",
  "{n} questions": "{n} câu hỏi",
  "What the plan covers": "Gói bao gồm những gì",
  "What you can use": "Bạn có thể sử dụng những gì",
  "Installation & report package": "Gói cơ sở & báo cáo",
  "Provided + 1 meeting session": "Được cung cấp + 1 buổi họp",
  "1 business day": "1 ngày làm việc",
  "Smart link": "Smart link",
  "Smart upload counts pages: an Excel file is 1 page, and every image inside it counts as one more page.":
    "Tải lên thông minh tính theo trang: một tệp Excel tính là 1 trang, và mỗi hình ảnh trong đó tính thêm một trang.",
  "Suppliers and precursor suppliers enter and fill in through their smart link on every plan — no cap, no account, no seat.":
    "Nhà cung cấp và nhà cung cấp tiền chất nhập và điền dữ liệu qua smart link của họ trong mọi gói — không giới hạn, không cần tài khoản, không chiếm chỗ ngồi.",
  "One company": "Một công ty",
  Widest: "Rộng nhất",
  "One company, one installation, one CN code.":
    "Một công ty, một cơ sở, một mã CN.",
  "Two installations and three CN codes, with a chain behind them.":
    "Hai cơ sở và ba mã CN, kèm theo chuỗi phía sau.",
  "Three installations and six CN codes, with the most room to work.":
    "Ba cơ sở và sáu mã CN, với nhiều không gian làm việc nhất.",
  "Your {plan} plan covers a single installation, and it is registered.":
    "Gói {plan} của bạn bao phủ một cơ sở duy nhất, và cơ sở đó đã được đăng ký.",
  "Your {plan} plan covers {cap} installations, and all of them are registered.":
    "Gói {plan} của bạn bao phủ {cap} cơ sở, và tất cả đều đã được đăng ký.",
  "Talk to sales to raise it — suppliers and precursor suppliers can still fill in through their link, without limit.":
    "Liên hệ bộ phận kinh doanh để nâng giới hạn — nhà cung cấp và nhà cung cấp tiền chất vẫn có thể điền dữ liệu qua liên kết của họ, không giới hạn.",
  "Seats used. Suppliers fill in through their link without limit.":
    "Chỗ ngồi đã dùng. Nhà cung cấp điền dữ liệu qua liên kết của họ, không giới hạn.",
  "Your team and what each person can do. Suppliers never take a seat — they fill in through a link, without an account.":
    "Nhóm của bạn và những việc mỗi người có thể làm. Nhà cung cấp không bao giờ chiếm chỗ ngồi — họ điền dữ liệu qua liên kết, không cần tài khoản.",
  "Every seat on your plan is taken. Remove someone to release a seat, or talk to sales — suppliers never take a seat.":
    "Mọi chỗ ngồi trong gói của bạn đã được sử dụng. Xóa một người để giải phóng chỗ ngồi, hoặc liên hệ bộ phận kinh doanh — nhà cung cấp không bao giờ chiếm chỗ ngồi.",
  "Suppliers and precursor suppliers fill in through their link without limit on every plan, at any chain depth, and never take a seat.":
    "Nhà cung cấp và nhà cung cấp tiền chất điền dữ liệu qua liên kết của họ không giới hạn trong mọi gói, ở mọi cấp độ chuỗi, và không bao giờ chiếm chỗ ngồi.",
